import {CLASSIC_ROSTER,resolveEquipment,getEquipmentArtPath} from './data.js?v=6.5.0';
import {getEnvironment,getActiveEnvironment,getEnvironmentProgress} from './classic-environments.js?v=6.5.0';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const check='<svg viewBox="0 0 30 30" aria-hidden="true"><circle cx="15" cy="15" r="13" fill="#25211b" stroke="#bdaa7c" stroke-width="2"/><path d="m8 15 5 5 9-10" fill="none" stroke="#f4eee0" stroke-width="2"/></svg>';
const kits={
 'company-contract':{characters:['1314','1304','1112']},'grail-contract':{characters:['1508','1509','1015']},'sp-contract':{characters:['1213','1306','1501']},'elation-contract':{characters:['1506','1501','8009']},'quantum-contract':{characters:['1208','1102']},
 'red-nobility':{items:['red-gem']},'blue-nobility':{items:['blue-gem']},
};
function rewardPreview(def){
 const kit=kits[def.id]||def,characters=kit.characters||[],items=kit.items||[];
 return `<div class="environment-reward-preview">${characters.length?`<span class="environment-reward-label">角色</span><div class="environment-preview-row">${characters.map(id=>{const c=CLASSIC_ROSTER.find(c=>c.id===id);return c?`<span class="environment-preview-portrait" title="${esc(c.name)}"><img src="${c.image}" alt="${esc(c.name)}"><small>★</small></span>`:'';}).join('')}</div>`:''}${items.length?`<span class="environment-reward-label">装备</span><div class="environment-preview-row">${items.map(id=>`<span class="environment-preview-item" title="${esc(resolveEquipment(id)?.name||id)}"><img src="${getEquipmentArtPath(id)}" alt="${esc(resolveEquipment(id)?.name||id)}"></span>`).join('')}</div>`:''}</div>`;
}
export function environmentScreen(state,selectedIndex=null){
 const offers=(state.environment?.choices||[]).map(getEnvironment),chosen=Number.isInteger(selectedIndex)?offers[selectedIndex]:null;
 return `<div class="reference-overlay"><section class="reference-fullscreen reference-choice-screen environment-screen" role="dialog" aria-modal="true" aria-labelledby="modal-heading"><div class="reference-mesh" aria-hidden="true"></div><div class="reference-choice-stage">零和博弈 · 开局准备</div><header class="reference-choice-heading"><i></i><h1 id="modal-heading">投资环境</h1><i></i></header><div class="reference-choice-cards">${offers.map((def,i)=>`<div class="reference-choice-column"><button class="reference-choice-card environment-choice-card ${i===selectedIndex?'is-selected':''}" data-action="environment-select" data-index="${i}" aria-pressed="${i===selectedIndex}" aria-label="${esc(def.name)}：${esc(def.description)}"><span class="environment-card-background"></span><span class="environment-emblem"><img src="${def.image}" alt=""></span><span class="environment-title">${esc(def.name)}</span><span class="environment-description">${esc(def.description)}</span>${rewardPreview(def)}</button></div>`).join('')}</div><div class="environment-choice-footer"><button class="environment-reroll" data-action="environment-reroll" ${state.environment?.rerolls?'':'disabled'}><span>↻</span>剩余次数：${state.environment?.rerolls||0}</button><button class="reference-confirm-button" data-action="environment-confirm" ${chosen?'':'disabled'}>${check}<span>确认</span></button></div><span class="reference-screen-signature">经典回响 · 非官方同人</span></section></div>`;
}
export function environmentSummary(state){const def=getActiveEnvironment(state);return def?`<button class="environment-open" data-action="environment-info" title="${esc(def.description)}"><img src="${def.image}" alt=""><span>${esc(def.name)}<small>${esc(getEnvironmentProgress(state))}</small></span></button>`:'';}
export function environmentDetails(state){
 const def=getActiveEnvironment(state);if(!def)return '';
 return `<div class="modal-backdrop"><section class="modal environment-details-modal" role="dialog" tabindex="-1" aria-modal="true" aria-labelledby="modal-heading"><button class="growth-close" data-action="close" aria-label="关闭投资环境">×</button><img class="environment-detail-icon" src="${def.image}" alt=""><small>本局投资环境</small><h2 id="modal-heading">${esc(def.name)}</h2><p>${esc(def.description)}</p><div class="environment-detail-progress">${esc(getEnvironmentProgress(state))}</div>${rewardPreview(def)}${def.note?`<p class="helper-note">${esc(def.note)}</p>`:''}<p class="helper-note">环境奖励以晶矿掉落，返回备战台点击领取。环境进度随本局保存。</p><button class="primary-button" data-action="close">返回备战界面</button></section></div>`;
}
